import React, { useState, useEffect } from "react";
import axios from "axios";
import { useCart } from "../components/CartContext";
import { useNavigate } from "react-router-dom";



const Products = () => {
  const [products, setProducts] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [file, setFile] = useState(null);
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [showViewModal, setShowViewModal] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const [categories, setCategories] = useState([]);
  const [brands, setBrands] = useState([]);
  const [categoryFilter, setCategoryFilter] = useState("");
  const [brandFilter, setBrandFilter] = useState("");
  const [priceFilter, setPriceFilter] = useState("");
  const [formData, setFormData] = useState({
    name: "",
    category: "",
    price: "",
    brand: "",
  });


const navigate = useNavigate();
const role = localStorage.getItem("role");


  useEffect(() => {
    axios.get("http://localhost:5000/api/users/allcategories").then(res => setCategories(res.data)).catch(console.error);
    axios.get("http://localhost:5000/api/users/allbrands").then(res => setBrands(res.data)).catch(console.error);
    axios.get("http://localhost:5000/api/users/allproducts").then(res => setProducts(res.data)).catch(console.error);
  }, []);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleFileChange = (e) => {
    setFile(e.target.files[0]);
  };

  const handleAddProduct = async (e) => {
    e.preventDefault();
    const formDataToSend = new FormData();
    formDataToSend.append("name", formData.name);
    formDataToSend.append("category", formData.category);
    formDataToSend.append("price", formData.price);
    formDataToSend.append("brand", formData.brand);
    formDataToSend.append("image", file);
    try {
       const token = localStorage.getItem("token");
      const res = await axios.post("http://localhost:5000/api/users/addproduct", formDataToSend, {
        headers: { "Content-Type": "multipart/form-data" ,
           "Authorization": `Bearer ${token}`,
        },
      });
      setProducts([res.data, ...products]);
      setFormData({ name: "", category: "", price: "", brand: "" });
      setFile(null);
      setShowForm(false);
    } catch (err) {
      alert(err.response?.data?.message || "Error adding product");
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm("Are you sure you want to delete this product?")) return;
    try {

      await axios.delete(`http://localhost:5000/api/users/product/${id}`);
      setProducts(products.filter((p) => p._id !== id));
    } catch {
      alert("Failed to delete product");
    }
  };

 const { addToCart, cartItems } = useCart(); // make sure addToCart is included!

const handleAddToCart = (product) => {
  addToCart(product);
  alert(`Added ${product.name} to cart!`);
};


  const filteredProducts = products.filter((product) => {
    const matchesSearch = product.name.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = categoryFilter ? product.category.toLowerCase() === categoryFilter.toLowerCase() : true;
    const matchesBrand = brandFilter ? product.brand.toLowerCase() === brandFilter.toLowerCase() : true;
    const matchesPrice = (() => {
      if (!priceFilter) return true;
      const price = Number(product.price);
      if (priceFilter === "0-1000") return price >= 0 && price <= 1000;
      if (priceFilter === "1000-1500") return price > 1000 && price <= 1500;
      if (priceFilter === "1500-2000") return price > 1500 && price <= 2000;
      if (priceFilter === "2000-3000") return price > 2000 && price <= 3000;
      if (priceFilter === "3000+") return price > 3000;
      return true;
    })();
    return matchesSearch && matchesCategory && matchesBrand && matchesPrice;
  });

  return (
    <div style={{ background: "linear-gradient(to right, #181c24, #232a36)", minHeight: "100vh", color: "#e0eafc", fontFamily: "'Segoe UI', Arial, sans-serif" }}>
      <h1 style={{ textAlign: "center", marginTop: "20px", color: "#60a5fa" }}>Products</h1>

      <div className="filter-bar" style={{ background: "#232a36", borderRadius: "12px", padding: "20px", margin: "0 auto 24px auto", maxWidth: "1200px", boxShadow: "0 2px 8px rgba(96,165,250,0.10)" }}>
        <select value={categoryFilter} onChange={(e) => setCategoryFilter(e.target.value)} style={{ background: "#181c24", color: "#e0eafc", border: "1px solid #374151", borderRadius: "8px", padding: "8px 12px", fontSize: "15px" }}>
          <option value="">All Categories</option>
          {categories.map((c) => <option key={c._id} value={c.name}>{c.name}</option>)}
        </select>

        <select value={brandFilter} onChange={(e) => setBrandFilter(e.target.value)} style={{ background: "#181c24", color: "#e0eafc", border: "1px solid #374151", borderRadius: "8px", padding: "8px 12px", fontSize: "15px" }}>
          <option value="">All Brands</option>
          {brands.map((b) => <option key={b._id} value={b.name}>{b.name}</option>)}
        </select>

        <select value={priceFilter} onChange={(e) => setPriceFilter(e.target.value)} style={{ background: "#181c24", color: "#e0eafc", border: "1px solid #374151", borderRadius: "8px", padding: "8px 12px", fontSize: "15px" }}>
          <option value="">All Prices</option>
          <option value="0-1000">₹0 - ₹1000</option>
          <option value="1000-1500">₹1000 - ₹1500</option>
          <option value="1500-2000">₹1500 - ₹2000</option>
          <option value="2000-3000">₹2000 - ₹3000</option>
          <option value="3000+">₹3000+</option>
        </select>

        <input type="text" placeholder="Search..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} style={{ background: "#181c24", color: "#e0eafc", border: "1px solid #374151", borderRadius: "8px", padding: "8px 12px", fontSize: "15px" }} />

        {role === "admin" && (
          <button onClick={() => setShowForm(true)} style={{ background: "#2563eb", color: "#fff", border: "none", borderRadius: "8px", padding: "8px 18px", fontWeight: 600, fontSize: "15px", marginLeft: "8px", cursor: "pointer" }}>Add Product</button>
        )}
        <button onClick={() => {
          setCategoryFilter("");
          setBrandFilter("");
          setPriceFilter("");
          setSearchTerm("");
        }} style={{ background: "#374151", color: "#e0eafc", border: "none", borderRadius: "8px", padding: "8px 18px", fontWeight: 600, fontSize: "15px", marginLeft: "8px", cursor: "pointer" }}>Reset</button>
      </div>

      {showForm && role === "admin" && (
        <form className="add-form" onSubmit={handleAddProduct} style={{ background: "#232a36", color: "#e0eafc", borderRadius: "12px", boxShadow: "0 2px 8px rgba(96,165,250,0.10)", padding: "24px", margin: "0 auto 24px auto", maxWidth: "600px", display: "flex", flexDirection: "column", gap: "12px" }}>
          <input type="text" name="name" value={formData.name} onChange={handleChange} placeholder="Product Name" required style={{ background: "#181c24", color: "#e0eafc", border: "1px solid #374151", borderRadius: "8px", padding: "10px", fontSize: "15px" }} />
          <select name="category" value={formData.category} onChange={handleChange} required style={{ background: "#181c24", color: "#e0eafc", border: "1px solid #374151", borderRadius: "8px", padding: "10px", fontSize: "15px" }}>
            <option value="">Select Category</option>
            {categories.map((c) => <option key={c._id} value={c.name}>{c.name}</option>)}
          </select>
          <select name="brand" value={formData.brand} onChange={handleChange} required style={{ background: "#181c24", color: "#e0eafc", border: "1px solid #374151", borderRadius: "8px", padding: "10px", fontSize: "15px" }}>
            <option value="">Select Brand</option>
            {brands.map((b) => <option key={b._id} value={b.name}>{b.name}</option>)}
          </select>
          <input type="number" name="price" value={formData.price} onChange={handleChange} placeholder="Price" required style={{ background: "#181c24", color: "#e0eafc", border: "1px solid #374151", borderRadius: "8px", padding: "10px", fontSize: "15px" }} />
          <input type="file" onChange={handleFileChange} required style={{ background: "#181c24", color: "#e0eafc", border: "1px solid #374151", borderRadius: "8px", padding: "10px", fontSize: "15px" }} />
          <button type="submit" style={{ background: "#2563eb", color: "#fff", border: "none", borderRadius: "8px", padding: "10px 24px", fontWeight: 600, fontSize: "16px", marginRight: "10px", cursor: "pointer" }}>Submit</button>
          <button type="button" onClick={() => setShowForm(false)} style={{ background: "#ef4444", color: "#fff", border: "none", borderRadius: "8px", padding: "10px 24px", fontWeight: 600, fontSize: "16px", cursor: "pointer" }}>Cancel</button>
        </form>
      )}
{cartItems.length > 0 && (
  <button className="floating-cart-btn" onClick={() => navigate("/cart")}>
    🛒 {cartItems.length}
  </button>
)}


      <div className="product-grid" style={{ background: "#181c24", borderRadius: "12px", padding: "24px 0", boxShadow: "0 2px 8px rgba(96,165,250,0.08)" }}>
        {filteredProducts.map((product) => (
          <div key={product._id} className="square-card" style={{ background: "#232a36", color: "#e0eafc", borderRadius: "12px", boxShadow: "0 4px 16px rgba(96,165,250,0.10)", border: "1px solid #374151" }}>
            <img src={`http://localhost:5000/uploads/${product.image}`} alt={product.name} className="square-img" style={{ background: "#181c24" }} />
            <div className="square-info">
              <h4 style={{ color: "#60a5fa" }}>{product.name}</h4>
              <div className="product-meta">{product.category}</div>
              <div className="product-meta">{product.brand}</div>
              <div className="product-meta">₹{product.price}</div>
              <div className="button-row">
                <button className="square-btn view" style={{ background: "#22d3ee", color: "#181c24" }} onClick={() => { setSelectedProduct(product); setShowViewModal(true); }}>View</button>
                {role === "admin" && (
                  <button className="square-btn delete" style={{ background: "#ef4444", color: "#fff" }} onClick={() => handleDelete(product._id)}>Delete</button>
                )}
              </div>
              <button className="square-btn view" style={{ background: "#2563eb", color: "#fff", marginTop: "10px" }} onClick={() => handleAddToCart(product)}>Add to Cart 🛒</button>
            </div>
          </div>
        ))}
      </div>

      {showViewModal && selectedProduct && (
        <div className="modal-overlay" style={{ background: "rgba(24,28,36,0.95)" }}>
          <div className="modal-box" style={{ background: "#232a36", color: "#e0eafc", borderRadius: "12px", boxShadow: "0 4px 24px rgba(96,165,250,0.12)", padding: "32px" }}>
            <h2 style={{ color: "#60a5fa" }}>{selectedProduct.name}</h2>
            <img src={`http://localhost:5000/uploads/${selectedProduct.image}`} alt={selectedProduct.name} className="square-img" style={{ background: "#181c24" }} />
            <p>Category: {selectedProduct.category}</p>
            <p>Brand: {selectedProduct.brand}</p>
            <p>Price: ₹{selectedProduct.price}</p>
            <button onClick={() => setShowViewModal(false)} style={{ background: "#374151", color: "#e0eafc", border: "none", borderRadius: "8px", padding: "10px 24px", fontWeight: 600, fontSize: "16px", cursor: "pointer", marginTop: "16px" }}>Close</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Products;
